1	const { normalizedContent } = require('./agent_event_utils');
2	const { claudeChangedPaths, claudeUsage } = require('./agent_claude_events');
3	const { isMissingSession } = require('./agent_provider_protocol');
4	
5	const CLAUDE_APPROVAL_DECISIONS = ['accept', 'acceptForSession', 'decline', 'cancel'];
6	const CLAUDE_FILE_TOOLS = new Set(['Edit', 'MultiEdit', 'NotebookEdit', 'Write']);
7	const CLAUDE_QUESTION_TOOL = 'AskUserQuestion';
8	
9	function requireMessage(content) {
10	    if (typeof content !== 'string' || content.trim().length === 0) throw new Error('Streaming agent message is required');
11	
12	    return content;
13	}
14	
15	function claudeUserMessage(content) {
16	    return { message: { content, role: 'user' }, type: 'user' };
17	}
18	
19	function claudeControlResponse(requestId, response) {
20	    return {
21	        response: { request_id: requestId, response, subtype: 'success' },
22	        type: 'control_response',
23	    };
24	}
25	
26	function claudeQuestionRequest(event) {
27	    if (event.type !== 'control_request' || event.request?.subtype !== 'can_use_tool') return null;
28	    if (event.request.tool_name !== CLAUDE_QUESTION_TOOL || !Array.isArray(event.request.input?.questions)) return null;
29	
30	    const questions = event.request.input.questions.map((question, index) => ({
31	        ...question,
32	        id: question.id ?? `claude-question-${index}`,
33	    }));
34	
35	    return {
36	        input: event.request.input,
37	        questions,
38	        requestId: event.request_id,
39	        toolUseId: event.request.tool_use_id,
40	    };
41	}
42	
43	function approvalFilePaths(toolName, input) {
44	    if (!CLAUDE_FILE_TOOLS.has(toolName) || !input || typeof input !== 'object' || Array.isArray(input)) return [];
45	    const filePath = toolName === 'NotebookEdit' ? input.notebook_path : input.file_path;
46	
47	    return typeof filePath === 'string' && filePath.length > 0 ? [filePath] : [];
48	}
49	
50	function claudeApprovalRequest(event) {
51	    if (event.type !== 'control_request' || event.request?.subtype !== 'can_use_tool') return null;
52	    if (event.request.tool_name === CLAUDE_QUESTION_TOOL) return null;
53	    const { input, permission_suggestions: permissionSuggestions, tool_name: toolName, tool_use_id: toolUseId } = event.request;
54	    if (event.request_id === undefined || event.request_id === null) throw new Error('Missing Claude approval request id');
55	    if (typeof toolName !== 'string' || toolName.length === 0) throw new Error('Missing Claude approval tool name');
56	    if (typeof toolUseId !== 'string' || toolUseId.length === 0) throw new Error('Missing Claude approval tool use id');
57	    if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('Missing Claude approval input');
58	    if (permissionSuggestions !== undefined && !Array.isArray(permissionSuggestions)) {
59	        throw new Error('Invalid Claude approval permission suggestions');
60	    }
61	    const availableDecisions = permissionSuggestions?.length > 0
62	        ? CLAUDE_APPROVAL_DECISIONS
63	        : CLAUDE_APPROVAL_DECISIONS.filter((decision) => decision !== 'acceptForSession');
64	    const approval = {
65	        approvalId: toolUseId,
66	        availableDecisions,
67	        command: toolName === 'Bash' && typeof input.command === 'string' ? input.command : null,
68	        cwd: typeof input.cwd === 'string' ? input.cwd : null,
69	        filePaths: approvalFilePaths(toolName, input),
70	        input: structuredClone(input),
71	        itemId: toolUseId,
72	        kind: toolName === 'Bash' ? 'commandExecution' : CLAUDE_FILE_TOOLS.has(toolName) ? 'fileChange' : 'toolUse',
73	        permissionSuggestions: structuredClone(permissionSuggestions ?? []),
74	        provider: 'claude',
75	        reason: event.request.decision_reason ?? event.request.reason ?? null,
76	        requestId: event.request_id,
77	        startedAtMs: Date.now(),
78	        toolName,
79	    };
80	
81	    return { approval, input, permissionSuggestions: permissionSuggestions ?? [], toolUseId };
82	}
83	
84	function claudeApprovalResponse(pendingApproval, decision) {
85	    const { input, permissionSuggestions, toolUseId } = pendingApproval;
86	    if (decision === 'accept') return { behavior: 'allow', toolUseID: toolUseId, updatedInput: input };
87	    if (decision === 'acceptForSession') {
88	        return {
89	            behavior: 'allow',
90	            toolUseID: toolUseId,
91	            updatedInput: input,
92	            updatedPermissions: permissionSuggestions,
93	        };
94	    }
95	    if (decision === 'decline') {
96	        return { behavior: 'deny', message: 'User declined this tool request', toolUseID: toolUseId };
97	    }
98	
99	    return { behavior: 'deny', interrupt: true, message: 'User stopped the turn', toolUseID: toolUseId };
100	}
101	
102	function isClaudeMissingSessionResult(event, providerConversationId) {
103	    if (!providerConversationId || event.type !== 'result' || event.is_error !== true) return false;
104	    if (event.session_id !== providerConversationId || !Array.isArray(event.errors)) return false;
105	
106	    return event.errors.includes(`No conversation found with session ID: ${providerConversationId}`);
107	}
108	
109	function eventBase(providerItemId, type, label, status = 'inProgress') {
110	    return { content: '', label, providerItemId, status, type };
111	}
112	
113	function toolInputContent(input) {
114	    if (typeof input === 'string') return input;
115	
116	    return JSON.stringify(input ?? {});
117	}
118	
119	function claudeToolEvent(block, status = 'inProgress', providerItemId = block.id) {
120	    const base = eventBase(providerItemId, `tool.${block.name}`, block.name, status);
121	    if (block.name === 'Bash') {
122	        return {
123	            ...base,
124	            command: block.input?.command,
125	            content: block.input?.command ?? toolInputContent(block.input),
126	            label: block.input?.command ?? 'Bash',
127	            type: 'commandExecution',
128	            workingDirectory: block.input?.cwd,
129	        };
130	    }
131	    if (CLAUDE_FILE_TOOLS.has(block.name)) {
132	        const filePaths = approvalFilePaths(block.name, block.input);
133	        const content = typeof block.input === 'string' ? block.input : filePaths.join('\n');
134	
135	        return { ...base, content, label: block.name, type: 'fileChange' };
136	    }
137	
138	    return { ...base, content: toolInputContent(block.input) };
139	}
140	
141	class ClaudeStreamingAdapter {
142	    constructor(writeLine, onEvent, rootPath, providerConversationId) {
143	        this.writeLine = writeLine;
144	        this.onEvent = onEvent;
145	        this.pendingApprovals = new Map();
146	        this.pendingQuestions = new Map();
147	        this.providerConversationId = providerConversationId;
148	        this.rootPath = rootPath;
149	        this.activeBlocks = new Map();
150	        this.streamedTextItems = new Map();
151	        this.activeMessageId = null;
152	        this.diagnosticSequence = 1;
153	        this.turnStarted = false;
154	        this.turnHasAssistantText = false;
155	    }
156	
157	    async start(prompt) {
158	        await this.sendMessage(prompt);
159	    }
160	
161	    async sendMessage(content) {
162	        await this.writeLine(claudeUserMessage(requireMessage(content)));
163	    }
164	
165	    async answerQuestion(requestId, answers) {
166	        const pendingQuestion = this.pendingQuestions.get(requestId);
167	        if (!pendingQuestion) throw new Error(`Unknown Claude question request id: ${requestId}`);
168	        const mappedAnswers = Object.fromEntries(pendingQuestion.questions.map(({ id, question }) => {
169	            if (!Object.hasOwn(answers, id)) throw new Error(`Missing answer for Claude question: ${id}`);
170	
171	            return [question, answers[id]];
172	        }));
173	        const updatedInput = { ...pendingQuestion.input, answers: mappedAnswers };
174	        const response = { behavior: 'allow', toolUseID: pendingQuestion.toolUseId, updatedInput };
175	        await this.writeLine(claudeControlResponse(requestId, response));
176	        this.pendingQuestions.delete(requestId);
177	    }
178	
179	    async answerApproval(requestId, decision) {
180	        const pendingApproval = this.pendingApprovals.get(requestId);
181	        if (!pendingApproval) throw new Error(`Unknown or stale Claude approval request id: ${requestId}`);
182	        if (pendingApproval.submitted) throw new Error(`Claude approval request was already submitted: ${requestId}`);
183	        if (!pendingApproval.approval.availableDecisions.includes(decision)) {
184	            throw new Error(`Unsupported Claude approval decision for request ${requestId}`);
185	        }
186	        const response = claudeApprovalResponse(pendingApproval, decision);
187	        pendingApproval.submitted = true;
188	        try {
189	            await this.writeLine(claudeControlResponse(requestId, response));
190	        } catch (error) {
191	            pendingApproval.submitted = false;
192	            throw error;
193	        }
194	        await this.onEvent({ requestId, type: 'approvalSubmitted' });
195	        this.pendingApprovals.delete(requestId);
196	        await this.onEvent({ requestId, type: 'approvalResolved' });
197	    }
198	
199	    async handleMessage(event) {
200	        const questionRequest = claudeQuestionRequest(event);
201	        if (questionRequest) {
202	            this.pendingQuestions.set(questionRequest.requestId, questionRequest);
203	            await this.onEvent({
204	                questions: questionRequest.questions,
205	                requestId: questionRequest.requestId,
206	                type: 'question',
207	            });
208	            return;
209	        }
210	        const approvalRequest = claudeApprovalRequest(event);
211	        if (approvalRequest) {
212	            if (this.pendingApprovals.has(approvalRequest.approval.requestId)) {
213	                throw new Error(`Duplicate Claude approval request id: ${approvalRequest.approval.requestId}`);
214	            }
215	            this.pendingApprovals.set(approvalRequest.approval.requestId, { ...approvalRequest, submitted: false });
216	            await this.onEvent({ approval: approvalRequest.approval, type: 'approval' });
217	            return;
218	        }
219	        if (event.type === 'control_request' && event.request?.subtype === 'can_use_tool') {
220	            throw new Error('Invalid Claude question request');
221	        }
222	        if (event.type === 'system' && typeof event.session_id === 'string') {
223	            await this.onEvent({ conversationId: event.session_id, type: 'sessionStarted' });
224	        }
225	        if (event.type === 'system') {
226	            if (event.subtype !== 'init') await this.emitDiagnostic(`Claude system event: ${event.subtype ?? 'unknown'}`);
227	            return;
228	        }
229	        if (event.type === 'stream_event') {
230	            await this.handleStreamEvent(event.event);
231	            return;
232	        }
233	        if (event.type === 'assistant') {
234	            await this.handleAssistantCompletion(event);
235	            return;
236	        }
237	        if (event.type === 'user') {
238	            await this.ensureTurnStarted();
239	            await this.handleToolResults(event);
240	            return;
241	        }
242	        if (event.type === 'result') {
243	            await this.handleResult(event);
244	            return;
245	        }
246	        await this.emitDiagnostic(`unsupported Claude event: ${event.type ?? 'unknown'}`);
247	    }
248	
249	    async ensureTurnStarted() {
250	        if (this.turnStarted) return;
251	        this.turnStarted = true;
252	        await this.onEvent({ type: 'turnStarted' });
253	    }
254	
255	    async handleStreamEvent(streamEvent) {
256	        if (!streamEvent || typeof streamEvent.type !== 'string') {
257	            await this.emitDiagnostic('invalid stream event');
258	            return;
259	        }
260	        if (streamEvent.type === 'message_start') {
261	            await this.ensureTurnStarted();
262	            this.activeMessageId = streamEvent.message?.id;
263	            this.activeBlocks.clear();
264	            if (typeof this.activeMessageId !== 'string' || this.activeMessageId.length === 0) {
265	                await this.emitDiagnostic('message_start missing message id');
266	            }
267	            return;
268	        }
269	        if (streamEvent.type === 'content_block_start') {
270	            await this.handleContentBlockStart(streamEvent);
271	            return;
272	        }
273	        if (streamEvent.type === 'content_block_delta') {
274	            await this.handleContentBlockDelta(streamEvent);
275	            return;
276	        }
277	        if (streamEvent.type === 'content_block_stop' || streamEvent.type === 'message_delta' || streamEvent.type === 'message_stop') return;
278	        await this.emitDiagnostic(`unsupported stream event: ${streamEvent.type}`);
279	    }
280	
281	    async handleContentBlockStart(streamEvent) {
282	        if (!Number.isSafeInteger(streamEvent.index) || !streamEvent.content_block || typeof this.activeMessageId !== 'string') {
283	            await this.emitDiagnostic('invalid content_block_start');
284	            return;
285	        }
286	        const block = structuredClone(streamEvent.content_block);
287	        const providerItemId = block.id ?? `${this.activeMessageId}:${block.type}:${streamEvent.index}`;
288	        const separator = block.type === 'text' && this.turnHasAssistantText ? '\n\n' : '';
289	        const trackedBlock = { block, inputJson: '', providerItemId, separator, text: block.text ?? block.thinking ?? '' };
290	        this.activeBlocks.set(streamEvent.index, trackedBlock);
291	        if (block.type === 'text') {
292	            // Keyed by stable providerItemId so the later aggregated `assistant` message reconciles
293	            // even after `message_start` of the next step has cleared `activeBlocks`.
294	            this.streamedTextItems.set(providerItemId, { separator });
295	            await this.onEvent({ itemId: providerItemId, type: 'assistantStarted' });
296	            if (separator.length > 0) await this.onEvent({ content: separator, itemId: providerItemId, type: 'assistant' });
297	            return;
298	        }
299	        if (block.type === 'thinking') {
300	            const event = {
301	                ...eventBase(providerItemId, 'reasoning', 'Thinking'),
302	                content: trackedBlock.text,
303	                details: [trackedBlock.text],
304	                summary: [],
305	            };
306	            await this.onEvent({ event, type: 'event' });
307	            return;
308	        }
309	        if (block.type === 'tool_use') await this.onEvent({ event: claudeToolEvent(block, 'inProgress', providerItemId), type: 'event' });
310	    }
311	
312	    async handleContentBlockDelta(streamEvent) {
313	        const trackedBlock = this.activeBlocks.get(streamEvent.index);
314	        if (!trackedBlock || !streamEvent.delta || typeof streamEvent.delta.type !== 'string') {
315	            await this.emitDiagnostic('invalid content_block_delta');
316	            return;
317	        }
318	        const { delta } = streamEvent;
319	        if (delta.type === 'text_delta' && typeof delta.text === 'string' && trackedBlock.block.type === 'text') {
320	            trackedBlock.text += delta.text;
321	            this.turnHasAssistantText = this.turnHasAssistantText || delta.text.length > 0;
322	            await this.onEvent({ content: delta.text, itemId: trackedBlock.providerItemId, type: 'assistant' });
323	            return;
324	        }
325	        if (delta.type === 'thinking_delta' && typeof delta.thinking === 'string' && trackedBlock.block.type === 'thinking') {
326	            trackedBlock.text += delta.thinking;
327	            const event = {
328	                ...eventBase(trackedBlock.providerItemId, 'reasoning', 'Thinking'),
329	                content: trackedBlock.text,
330	                details: [trackedBlock.text],
331	                summary: [],
332	            };
333	            await this.onEvent({ event, type: 'event' });
334	            return;
335	        }
336	        if (delta.type === 'input_json_delta' && typeof delta.partial_json === 'string' && trackedBlock.block.type === 'tool_use') {
337	            trackedBlock.inputJson += delta.partial_json;
338	            const updatedBlock = { ...trackedBlock.block, input: trackedBlock.inputJson };
339	            await this.onEvent({ event: claudeToolEvent(updatedBlock, 'inProgress', trackedBlock.providerItemId), type: 'event' });
340	            return;
341	        }
342	        if (delta.type !== 'signature_delta') await this.emitDiagnostic(`unsupported content delta: ${delta.type}`);
343	    }
344	
345	    async handleAssistantCompletion(event) {
346	        await this.ensureTurnStarted();
347	        if (!Array.isArray(event.message?.content)) {
348	            await this.emitDiagnostic('assistant message missing content');
349	            return;
350	        }
351	        const messageId = event.message.id ?? this.activeMessageId;
352	        if (typeof messageId !== 'string' || messageId.length === 0) throw new Error('Missing Claude assistant message id');
353	        for (const [index, block] of event.message.content.entries()) {
354	            const providerItemId = block.id ?? `${messageId}:${block.type}:${index}`;
355	            if (block.type === 'text' && typeof block.text === 'string') {
356	                const streamedItem = this.streamedTextItems.get(providerItemId);
357	                const separator = streamedItem?.separator ?? (this.turnHasAssistantText ? '\n\n' : '');
358	                if (!streamedItem) {
359	                    await this.onEvent({ itemId: providerItemId, type: 'assistantStarted' });
360	                }
361	                this.turnHasAssistantText = this.turnHasAssistantText || block.text.length > 0;
362	                await this.onEvent({ content: `${separator}${block.text}`, itemId: providerItemId, type: 'assistantCompleted' });
363	                continue;
364	            }
365	            if (block.type === 'thinking') {
366	                const content = typeof block.thinking === 'string' ? block.thinking : '';
367	                const reasoningEvent = {
368	                    ...eventBase(providerItemId, 'reasoning', 'Thinking', 'completed'),
369	                    content,
370	                    details: [content],
371	                    summary: [],
372	                };
373	                await this.onEvent({ event: reasoningEvent, type: 'event' });
374	                continue;
375	            }
376	            if (block.type === 'tool_use') await this.onEvent({ event: claudeToolEvent(block, 'inProgress', providerItemId), type: 'event' });
377	        }
378	        const changedPaths = claudeChangedPaths(event, this.rootPath);
379	        if (changedPaths.length > 0) await this.onEvent({ paths: changedPaths, type: 'changedPaths' });
380	    }
381	
382	    async handleToolResults(event) {
383	        if (!Array.isArray(event.message?.content)) return;
384	        for (const block of event.message.content) {
385	            if (block?.type !== 'tool_result' || typeof block.tool_use_id !== 'string') continue;
386	            const trackedTool = [...this.activeBlocks.values()].find(({ providerItemId }) => providerItemId === block.tool_use_id);
387	            const toolEvent = trackedTool?.block?.type === 'tool_use'
388	                ? claudeToolEvent(trackedTool.block, block.is_error ? 'failed' : 'completed')
389	                : eventBase(block.tool_use_id, 'tool.result', 'Tool result', block.is_error ? 'failed' : 'completed');
390	            toolEvent.output = normalizedContent(block.content) ?? '';
391	            await this.onEvent({ event: toolEvent, type: 'event' });
392	        }
393	    }
394	
395	    async handleResult(event) {
396	        const error = event.is_error === true
397	            ? String(event.error ?? event.result ?? event.message ?? event.errors?.join('\n') ?? 'Claude turn failed')
398	            : null;
399	        const missingSession = !this.turnStarted && (
400	            isClaudeMissingSessionResult(event, this.providerConversationId)
401	            || isMissingSession('claude', event, this.turnStarted)
402	        );
403	        for (const requestId of this.pendingApprovals.keys()) {
404	            this.pendingApprovals.delete(requestId);
405	            await this.onEvent({ requestId, type: 'approvalResolved' });
406	        }
407	        this.activeBlocks.clear();
408	        this.streamedTextItems.clear();
409	        this.activeMessageId = null;
410	        this.pendingQuestions.clear();
411	        this.turnStarted = false;
412	        this.turnHasAssistantText = false;
413	        await this.onEvent({ error, missingSession, type: 'turnCompleted', usage: claudeUsage(event) });
414	    }
415	
416	    async emitDiagnostic(content) {
417	        const providerItemId = `diagnostic:${this.activeMessageId ?? 'unknown-message'}:${this.diagnosticSequence}`;
418	        this.diagnosticSequence += 1;
419	        const event = { ...eventBase(providerItemId, 'diagnostic', 'Claude protocol diagnostic', 'completed'), content };
420	        await this.onEvent({ event, type: 'event' });
421	    }
422	}
423	
424	module.exports = { ClaudeStreamingAdapter };
425

